"""Review passes 1-3: game logic, fit with reality (Nov 2026), usefulness for solving the problem."""
from common import *
from a_game import K
from b_evidence import SRC

C = CREATED
def get(slug): return C[f'simorgh:{slug}']
def setp(slug, i, p):
    d = get(slug); d['points'][i] = p; _src(d, p)
def addp(slug, *ps, at=None):
    d = get(slug)
    for p in ps:
        if at is None: d['points'].append(p)
        else: d['points'].insert(at, p); at += 1
        _src(d, p)
def addl(slug, *ls):
    d = get(slug)
    for l in ls:
        if not any(x['to'] == l['to'] for x in d['links']): d['links'].append(l)
def _src(d, p):
    for k in p['sources']:
        if k not in d['sources']: d['sources'].append(k)

